def solution() -> int:
    m = len('es')
    n = len('bc')

    # Create a table of (m+1) rows and (n+1) columns
    dp = [[0]*(n+1) for _ in range(m+1)]

    # Fill dp table
    for i in range(1, m+1):
        for j in range(1, n+1):
            if 'es'[i-1] == 'bc'[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[m][n]

